// Where the site lives, shared by astro.config.mjs and scripts/sync-docs.mjs.
// GitHub Pages serves a project site at https://<user>.github.io/<repo>/, hence the base path.
// With a custom domain later: set SITE to it and BASE to "/".
export const SITE = "https://clon1998.github.io";
export const BASE = "/contrail";
export const REPO = "https://github.com/Clon1998/contrail";

/**
 * The Markdown files in `docs/` that become pages, and where. The pages are generated by
 * scripts/sync-docs.mjs, so `docs/` stays the single source (it also renders on GitHub).
 */
export const DOCS = [{ file: "query-syntax.md", slug: "search-syntax", label: "Search syntax" }];
